import java.io.*;
import java.net.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.xml.parsers.*;
import org.xml.sax.*;
import org.xml.sax.helpers.*;
import org.w3c.dom.*;

public class WebhookProcessorServlet extends HttpServlet {

    private static final Set<String> ALLOWED_EVENTS = Set.of(
        "order.created", "order.updated", "payment.received",
        "shipment.dispatched", "inventory.low"
    );

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String contentType = req.getContentType();
        if (contentType == null || !contentType.contains("xml")) {
            resp.sendError(415, "Content-Type must be application/xml");
            return;
        }

        String hmacHeader = req.getHeader("X-Webhook-Signature");
        if (hmacHeader == null || hmacHeader.length() < 32) {
            resp.sendError(401, "Missing or invalid signature");
            return;
        }

        // Read body with size limit
        byte[] body = req.getInputStream().readNBytes(65536);
        if (body.length >= 65536) {
            resp.sendError(413, "Payload too large");
            return;
        }

        // Verify HMAC (simplified - uses shared secret from env)
        String secret = System.getenv("WEBHOOK_SECRET");
        if (secret == null) {
            resp.sendError(500, "Configuration error");
            return;
        }

        // Parse the XML webhook payload
        try {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            // Attempt to limit entity expansion
            dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", false);
            dbf.setExpandEntityReferences(true);
            dbf.setFeature("http://xml.org/sax/features/external-general-entities", true);
            dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", true);
            dbf.setXIncludeAware(false);
            dbf.setNamespaceAware(true);

            DocumentBuilder db = dbf.newDocumentBuilder();
            Document doc = db.parse(new ByteArrayInputStream(body));

            // Extract event type and validate
            NodeList events = doc.getElementsByTagName("event");
            if (events.getLength() == 0) {
                resp.sendError(400, "No event element found");
                return;
            }

            Element eventEl = (Element) events.item(0);
            String eventType = eventEl.getAttribute("type");

            if (!ALLOWED_EVENTS.contains(eventType)) {
                resp.sendError(400, "Unknown event type: " + eventType);
                return;
            }

            // Extract payload data
            NodeList dataNodes = eventEl.getElementsByTagName("data");
            String payload = "";
            if (dataNodes.getLength() > 0) {
                payload = dataNodes.item(0).getTextContent();
            }

            // Process the webhook
            processEvent(eventType, payload);

            resp.setStatus(200);
            resp.getWriter().write("{\"status\":\"accepted\"}");

        } catch (ParserConfigurationException | SAXException e) {
            resp.sendError(400, "Invalid XML: " + e.getMessage());
        }
    }

    private void processEvent(String eventType, String data) {
        // Queue event for async processing
        System.out.println("Processing event: " + eventType + " with data length: " + data.length());
        // In production this would publish to SQS/Kafka
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setContentType("application/json");
        resp.getWriter().write("{\"service\":\"webhook-processor\",\"version\":\"2.4.1\"}");
    }
}
